// src/components/Gamification.js
import React, { useState, useEffect } from "react";

const Gamification = ({ user, language = "english" }) => {
  const [badges, setBadges] = useState([]);
  const [progress, setProgress] = useState(0);

  // --------- Translations ----------
  const translations = {
    hindi: {
      title: "आपकी उपलब्धियां",
      progress: "प्रगति",
      badgesEarned: "बैज अर्जित किए",
      of: "में से",
      badges: {
        newVoter: "नया मतदाता",
        eligibilityChecked: "पात्रता जांच पूरी",
        voterEducator: "मतदाता शिक्षक",
        communityLeader: "समुदाय नेता",
        registrationChampion: "पंजीकरण चैंपियन",
        informedCitizen: "सूचित नागरिक",
      },
    },
    english: {
      title: "Your Achievements",
      progress: "Progress",
      badgesEarned: "Badges Earned",
      of: "of",
      badges: {
        newVoter: "New Voter",
        eligibilityChecked: "Eligibility Checked",
        voterEducator: "Voter Educator",
        communityLeader: "Community Leader",
        registrationChampion: "Registration Champion",
        informedCitizen: "Informed Citizen",
      },
    },
  };

  const t = translations[language] || translations.english;

  // --------- Load "actual" user progress ----------
  const loadUserStats = () => {
    // agar parent se user object aata hai to pehle woh use karenge
    // warna localStorage se padhenge
    const ls = (key, fallback = null) =>
      window.localStorage.getItem(key) ?? fallback;

    const stats = {
      // e.g. eligibility checker ke baad set karo: localStorage.setItem("eligibility_checked", "true");
      eligibilityChecked:
        user?.eligibilityChecked ?? ls("eligibility_checked") === "true",

      // registration complete hone ke baad: localStorage.setItem("registration_completed", "true");
      registrationCompleted:
        user?.registrationCompleted ?? ls("registration_completed") === "true",

      // KnowYourCandidate me har baar successful answer ke baad 1 se increment karo
      // localStorage.setItem("ai_questions_asked", current + 1);
      aiQuestionsAsked: Number(
        user?.aiQuestionsAsked ?? ls("ai_questions_asked", "0")
      ),

      // future: awareness section / share button complete hone par
      sharedAwareness:
        user?.sharedAwareness ?? ls("shared_awareness") === "true",

      // koi basic profile / details complete hone par
      profileCompleted:
        user?.profileCompleted ?? ls("profile_completed") === "true",
    };

    return stats;
  };

  // --------- Badge definitions (conditions based on stats) ----------
  const getBadgesFromStats = (stats) => {
    const defs = [
      {
        id: 1,
        key: "newVoter",
        name: "New Voter",
        color: "#FF6B6B",
        shape: "circle",
        // almost sabko ye mil sakta hai – jaise profile complete ya first login
        condition: (s) => s.profileCompleted || true, // abhi demo ke liye default true
      },
      {
        id: 2,
        key: "eligibilityChecked",
        name: "Eligibility Checked",
        color: "#4ECDC4",
        shape: "star",
        condition: (s) => s.eligibilityChecked,
      },
      {
        id: 3,
        key: "voterEducator",
        name: "Voter Educator",
        color: "#45B7D1",
        shape: "hexagon",
        // maan lo agar user ne awareness share ki ya quiz complete ki
        condition: (s) => s.sharedAwareness,
      },
      {
        id: 4,
        key: "communityLeader",
        name: "Community Leader",
        color: "#FFA07A",
        shape: "square",
        // future: agar tum community actions count track karo
        condition: (s) => s.sharedAwareness && s.aiQuestionsAsked >= 3,
      },
      {
        id: 5,
        key: "registrationChampion",
        name: "Registration Champion",
        color: "#98D8C8",
        shape: "diamond",
        condition: (s) => s.registrationCompleted,
      },
      {
        id: 6,
        key: "informedCitizen",
        name: "Informed Citizen",
        color: "#F7DC6F",
        shape: "circle",
        // KnowYourCandidate se 3+ sawal puche → informed citizen
        condition: (s) => s.aiQuestionsAsked >= 3,
      },
    ];

    return defs.map((badge) => ({
      ...badge,
      earned: badge.condition(stats),
    }));
  };

  useEffect(() => {
    const stats = loadUserStats();
    const computedBadges = getBadgesFromStats(stats);

    setBadges(computedBadges);

    const earnedCount = computedBadges.filter((b) => b.earned).length;
    const total = computedBadges.length || 1;
    setProgress(Math.round((earnedCount / total) * 100));
  }, [user, language]);

  const getBadgeName = (badge) => {
    return t.badges[badge.key] || badge.name;
  };

  return (
    <div className="gamification">
      <h2>{t.title}</h2>

      <div className="progress-section">
        <h3>{t.progress}</h3>
        <div className="progress-bar">
          <div
            className="progress-fill"
            style={{ width: `${progress}%` }}
          ></div>
        </div>
        <p>
          {badges.filter((b) => b.earned).length} {t.of} {badges.length}{" "}
          {t.badgesEarned}
        </p>
      </div>

      <div className="badges-grid">
        {badges.map((badge) => (
          <div
            key={badge.id}
            className={`badge ${badge.earned ? "earned" : "locked"}`}
            style={{
              backgroundColor: badge.earned ? badge.color : "#CCCCCC",
              borderRadius:
                badge.shape === "circle"
                  ? "50%"
                  : badge.shape === "square"
                  ? "0"
                  : badge.shape === "star"
                  ? "50% 50% 0 0"
                  : "10px",
            }}
          >
            <div className="badge-icon">{badge.earned ? "✓" : "🔒"}</div>
            <div className="badge-name">{getBadgeName(badge)}</div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Gamification;
